const API_URL = 'http://127.0.0.1:8000';
const EffortLevels = ['low', 'medium', 'high', 'xhigh'];
const DemoAgents = [
  {id:'director',name:'DIRECTOR',role:'Dirección',tone:'#ffd166',hue:'-100deg',tokens_used:1260,token_budget:6000,reasoning_effort:'high',status:'sleeping',idle_mode:'Coffee',sleep:[36,44],work:[80,25],action:'priorizando'},
  {id:'nexus',name:'NEXUS',role:'Coordinación',tone:'#d9f45a',hue:'68deg',tokens_used:2870,token_budget:8000,reasoning_effort:'high',status:'sleeping',idle_mode:'Eating',sleep:[54,48],work:[51,17],action:'planificando'},
  {id:'scout',name:'SCOUT',role:'Investigación',tone:'#79e8ee',hue:'0deg',tokens_used:1920,token_budget:5500,reasoning_effort:'medium',status:'sleeping',idle_mode:'Sleep',sleep:[44,71],work:[18,28],action:'investigando'},
  {id:'forge',name:'FORGE',role:'Construcción',tone:'#ff789d',hue:'135deg',tokens_used:840,token_budget:7000,reasoning_effort:'medium',status:'sleeping',idle_mode:'Sleep',sleep:[58,71],work:[20,64],action:'construyendo'},
  {id:'sentinel',name:'SENTINEL',role:'Calidad',tone:'#ab8cff',hue:'230deg',tokens_used:610,token_budget:4500,reasoning_effort:'low',status:'sleeping',idle_mode:'Coffee',sleep:[39,34],work:[79,63],action:'revisando'},
  {id:'muse',name:'MUSE',role:'Dirección de arte',tone:'#ffaf5f',hue:'-45deg',tokens_used:430,token_budget:6200,reasoning_effort:'high',status:'sleeping',idle_mode:'Eating',sleep:[55,34],work:[49,33],action:'diseñando'}
];
const LoungeRoutes = {
  director: [[36,44], [38,53], [44,57], [32,49]],
  nexus: [[54,48], [61,53], [56,57], [63,44]],
  sentinel: [[39,34], [45,37], [43,29], [33,38]],
  muse: [[55,34], [61,38], [64,31], [52,29]]
};
const State = { agents: structuredClone(DemoAgents), events: [], selectedAgentId: 'nexus', connected: false, lastTelemetryAt: null, codexUsage: null, dashboardReady: false, knownDispatches: new Set(), eventSource: null, buildId: null, openAgentId: null, roomZoom: 1, roomPan: 0, roomPanY: 0 };
const $ = (selector) => document.querySelector(selector);
const formatNumber = (value) => new Intl.NumberFormat('es-ES').format(value);
const uppercase = (value) => value.toUpperCase();
const getSelectedAgent = () => State.agents.find((agent) => agent.id === State.selectedAgentId);
const fetchApi = async (path, options = {}) => { const response = await fetch(API_URL + path, {headers:{'Content-Type':'application/json'}, ...options}); if (!response.ok) throw new Error('API unavailable'); return response.json(); };

function renderControlPanel() { const agent = getSelectedAgent(); $('#agentSelect').innerHTML = State.agents.map((item) => `<option value="${item.id}">${item.name} — ${item.role}</option>`).join(''); $('#agentSelect').value = agent.id; $('#budgetInput').value = agent.token_budget; $('#effortSelector').innerHTML = EffortLevels.map((level) => `<button class="EffortButton ${agent.reasoning_effort === level ? 'Active' : ''}" data-effort="${level}">${uppercase(level)}</button>`).join(''); }
function renderMetricsPanel() { const used = State.agents.reduce((sum, agent) => sum + agent.tokens_used, 0); const budget = State.agents.reduce((sum, agent) => sum + agent.token_budget, 0); const active = State.agents.filter((agent) => agent.status === 'working').length; const usage = Math.min(100, Math.round((used / budget) * 100)); const margin = 100 - usage; const health = usage < 65 ? 'EFICIENTE' : usage < 85 ? 'VIGILAR' : 'REVISAR'; $('#budgetUsage').textContent = `${usage}%`; $('#budgetMargin').textContent = `${margin}%`; $('#activeAgents').textContent = `${active}/${State.agents.length}`; $('#budgetHealth').textContent = health; $('#budgetBar').style.width = `${usage}%`; $('#budgetNumbers').textContent = `${formatNumber(used)} / ${formatNumber(budget)} tokens`; $('#efficiencyMessage').textContent = usage < 65 ? 'Gasto bajo control' : usage < 85 ? 'Prioriza tareas complejas' : 'Ajusta límites'; $('#telemetryStamp').textContent = State.lastTelemetryAt ? `Actualizado ${State.lastTelemetryAt.toLocaleTimeString('es-ES', {hour:'2-digit', minute:'2-digit', second:'2-digit'})} · ${State.connected ? 'API en directo' : 'modo simulación'}` : 'Esperando telemetría'; }
function formatReset(unixSeconds) { if (!unixSeconds) return 'Sin dato de reinicio'; const date = new Date(unixSeconds * 1000); return `Reinicia ${date.toLocaleDateString('es-ES', {day:'2-digit', month:'short'})} · ${date.toLocaleTimeString('es-ES', {hour:'2-digit', minute:'2-digit'})}`; }
function renderCodexUsage() { const usage = State.codexUsage; if (!usage) return; if (!usage.available) { $('#codexUsageStatus').textContent = 'Uso local no disponible: abre Codex en este equipo.'; return; } const latestDay = usage.daily_buckets?.at(-1); $('#fiveHourRemaining').textContent = `${usage.five_hour.remaining_percent}%`; $('#weeklyRemaining').textContent = `${usage.weekly.remaining_percent}%`; $('#fiveHourReset').textContent = formatReset(usage.five_hour.resets_at); $('#weeklyReset').textContent = formatReset(usage.weekly.resets_at); $('#codexPlan').textContent = `Plan ${(usage.plan || '—').toUpperCase()}`; $('#resetCredits').textContent = `${usage.reset_credits} recargas`; $('#dailyTokens').textContent = latestDay ? `${formatNumber(latestDay.tokens)} tokens · último día` : 'Actividad sin datos'; $('#codexUsageStatus').textContent = `Datos reales de Codex · ${new Date(usage.refreshed_at).toLocaleTimeString('es-ES', {hour:'2-digit', minute:'2-digit', second:'2-digit'})}`; }
function renderActivityLog() { $('#activityLog').innerHTML = State.events.slice(0,4).map((event) => `<article class="ActivityItem"><time>${new Date(event.created_at).toLocaleTimeString('es-ES',{hour:'2-digit',minute:'2-digit'})}</time><div><b>${event.agent}</b><br><span>${event.message}</span></div></article>`).join('') || '<div class="ActivityItem"><time>—</time><span>Sin actividad aún.</span></div>'; }
function agentStateLabel(agent) { if (agent.visualPhase === 'commuting') return 'EN RUTA'; return agent.status === 'working' ? 'TRABAJANDO' : agent.idle_mode === 'Sleep' ? 'DESCANSANDO' : agent.idle_mode === 'Coffee' ? 'EN PAUSA' : 'RECARGANDO'; }
function agentActivityCopy(agent) { if (agent.visualPhase === 'commuting') return `Ha dejado su descanso y va hacia su puesto para ${agent.action}.`; if (agent.status === 'working') return `Está en su estación: ${agent.action}. El trabajo ya está en marcha.`; if (agent.idle_mode === 'Sleep') return 'Está recuperando energía en la zona de descanso y sigue disponible para una orden.'; if (agent.idle_mode === 'Coffee') return 'Está tomando café en la sala común, atento a la siguiente misión.'; return 'Está en la sala común recargando antes de asumir una nueva tarea.'; }
function createAgentWatchCard(agent) { return `<article class="AgentWatchCard" data-watch-agent-id="${agent.id}"><div class="AgentWatchTop"><span class="AgentSignal"></span><strong></strong><em></em></div><div class="AgentMiniScene"><i class="MiniGlow"></i><i class="MiniDesk"></i><i class="MiniCoffee"></i><i class="AgentFeedSlime"></i><i class="MiniParticles"></i></div><div class="AgentWatchBottom"><span class="AgentWatchRole"></span><span class="AgentWatchTokens"></span></div><button class="AgentInfoButton" type="button" data-agent-info="${agent.id}" aria-expanded="false">VER ACTIVIDAD <span>+</span></button><section class="AgentDetailPopover" hidden><button class="AgentPopoverClose" type="button" data-agent-info="${agent.id}" aria-label="Cerrar detalle">×</button><b></b><p></p><small></small></section></article>`; }
function updateAgentWatchCard(card, agent) { const state = agent.visualPhase === 'commuting' ? 'Commuting' : agent.status === 'working' ? 'Working' : `Resting ${agent.idle_mode}`; const usage = Math.round((agent.tokens_used / agent.token_budget) * 100); const expanded = State.openAgentId === agent.id; card.className = `AgentWatchCard ${state}${expanded ? ' IsExpanded' : ''}`; card.style.setProperty('--agent-tone', agent.tone); card.style.setProperty('--hue', agent.hue || '0deg'); card.querySelector('.AgentWatchTop strong').textContent = agent.name; card.querySelector('.AgentWatchTop em').textContent = agentStateLabel(agent); card.querySelector('.AgentWatchRole').textContent = agent.role; card.querySelector('.AgentWatchTokens').textContent = `${usage}% TOKENS`; const button = card.querySelector('.AgentInfoButton'); button.setAttribute('aria-expanded', String(expanded)); button.querySelector('span').textContent = expanded ? '−' : '+'; const popup = card.querySelector('.AgentDetailPopover'); popup.hidden = !expanded; popup.querySelector('b').textContent = `${agent.name} · ${agentStateLabel(agent)}`; popup.querySelector('p').textContent = agentActivityCopy(agent); popup.querySelector('small').textContent = `${formatNumber(agent.tokens_used)} / ${formatNumber(agent.token_budget)} tokens · esfuerzo ${uppercase(agent.reasoning_effort)}`; }
function renderAgentWatchPanels() { const rails = [$('#agentWatchRailLeft'), $('#agentWatchRailRight')]; const split = Math.ceil(State.agents.length / 2); [State.agents.slice(0, split), State.agents.slice(split)].forEach((agents, index) => { const rail = rails[index]; agents.forEach((agent) => { let card = rail.querySelector(`[data-watch-agent-id="${agent.id}"]`); if (!card) { rail.insertAdjacentHTML('beforeend', createAgentWatchCard(agent)); card = rail.querySelector(`[data-watch-agent-id="${agent.id}"]`); } updateAgentWatchCard(card, agent); }); }); }
function createSlimeUnit(agent) { return `<div class="SlimeUnit" data-agent-id="${agent.id}"><i class="WorkLabel"></i><i class="IdleProp"></i><i class="SlimeSprite" aria-hidden="true"></i><strong></strong></div>`; }
function updateSlimeUnit(element, agent) { const commuting = agent.visualPhase === 'commuting'; const [x, y] = agent.status === 'working' || commuting ? agent.work : agent.sleep; const stateClass = commuting ? `Commuting ${agent.idle_mode}` : agent.status === 'working' ? 'Working' : `Resting ${agent.idle_mode}${agent.moving ? ' Moving' : ''}`; element.className = `SlimeUnit ${stateClass}`; element.style.setProperty('--tone', agent.tone); element.style.setProperty('--hue', agent.hue || '0deg'); element.style.setProperty('--x', `${x}%`); element.style.setProperty('--y', `${y}%`); element.style.left = `${x}%`; element.style.top = `${y}%`; element.querySelector('.WorkLabel').textContent = commuting ? 'en ruta' : agent.action; element.querySelector('strong').textContent = agent.name; }
function renderSlimeRoom() { const world = $('#roomWorld'); world.style.setProperty('--room-zoom', State.roomZoom); world.style.setProperty('--room-pan-x', `${State.roomPan}%`); world.style.setProperty('--room-pan-y', `${State.roomPanY}%`); State.agents.forEach((agent) => { let element = world.querySelector(`[data-agent-id="${agent.id}"]`); if (!element) { world.insertAdjacentHTML('beforeend', createSlimeUnit(agent)); element = world.querySelector(`[data-agent-id="${agent.id}"]`); } updateSlimeUnit(element, agent); }); const activeNames = State.agents.filter((agent) => agent.status === 'working').map((agent) => agent.name); $('#roomStatus').textContent = activeNames.length ? activeNames.join(' + ') : 'Todos descansando'; }
function controlRoomCamera(command) { if (command === 'in') State.roomZoom = Math.min(1.14, +(State.roomZoom + .07).toFixed(2)); if (command === 'out') State.roomZoom = Math.max(.9, +(State.roomZoom - .07).toFixed(2)); if (command === 'left') State.roomPan = Math.max(-9, State.roomPan - 3); if (command === 'right') State.roomPan = Math.min(9, State.roomPan + 3); if (command === 'up') State.roomPanY = Math.max(-8, State.roomPanY - 3); if (command === 'down') State.roomPanY = Math.min(8, State.roomPanY + 3); if (command === 'center') { State.roomZoom = 1; State.roomPan = 0; State.roomPanY = 0; } renderSlimeRoom(); }
function renderDashboard() { renderControlPanel(); renderMetricsPanel(); renderCodexUsage(); renderActivityLog(); renderSlimeRoom(); renderAgentWatchPanels(); }
function updateConnectionLabel() { $('#apiStatus').textContent = State.connected ? '● API CONECTADA' : '● API DEMO'; $('#apiStatus').style.color = State.connected ? 'var(--acid)' : 'var(--cyan)'; }
function updateDigitalClock() { const now = new Date(); $('#digitalTime').textContent = now.toLocaleTimeString('es-ES', {hour:'2-digit', minute:'2-digit', second:'2-digit', hour12:false}); const date = new Intl.DateTimeFormat('es-ES', {weekday:'long', day:'2-digit', month:'short', year:'numeric'}).format(now).replace('.', '').toUpperCase(); $('#digitalDate').textContent = date.replace(',', ' ·'); }
function triggerWorkAnimation(agentIds) { const starting = State.agents.filter((agent) => agentIds.includes(agent.id) && agent.visualPhase !== 'commuting' && agent.visualPhase !== 'working'); if (!starting.length) return; starting.forEach((agent) => { agent.status = 'working'; agent.visualPhase = 'commuting'; }); renderSlimeRoom(); setTimeout(() => { starting.forEach((agent) => { if (agent.status === 'working') agent.visualPhase = 'working'; }); renderSlimeRoom(); }, 2700); }
function detectRemoteDispatches(events) { const dispatches = events.filter((event) => event.kind === 'mission_dispatched'); if (!State.dashboardReady) { dispatches.forEach((event) => State.knownDispatches.add(event.id)); State.dashboardReady = true; return; } const agentIds = dispatches.filter((event) => !State.knownDispatches.has(event.id)).map((event) => { State.knownDispatches.add(event.id); return State.agents.find((agent) => agent.name === event.agent)?.id; }).filter(Boolean); triggerWorkAnimation([...new Set(agentIds)]); }
function consumeDashboard(dashboard) { dashboard.agents.forEach((remoteAgent) => { const localAgent = State.agents.find((agent) => agent.id === remoteAgent.id); if (!localAgent) return; const status = remoteAgent.status === 'running' ? 'working' : 'sleeping'; Object.assign(localAgent, remoteAgent, {status}); if (status !== 'working') localAgent.visualPhase = undefined; }); detectRemoteDispatches(dashboard.events || []); State.events = dashboard.events || []; State.connected = true; State.lastTelemetryAt = new Date(); updateConnectionLabel(); renderDashboard(); }
async function syncDashboard() { consumeDashboard(await fetchApi('/api/dashboard')); }
function connectLiveStream() { if (State.eventSource) return; const stream = new EventSource(`${API_URL}/api/stream`); State.eventSource = stream; stream.onmessage = (event) => { try { consumeDashboard(JSON.parse(event.data)); } catch {} }; stream.onerror = () => { stream.close(); State.eventSource = null; }; }
async function checkForDeployment() { const response = await fetch(`app-version.json?check=${Date.now()}`, {cache:'no-store'}); if (!response.ok) return; const {buildId} = await response.json(); if (State.buildId && State.buildId !== buildId) { window.location.reload(); return; } State.buildId = buildId; }
async function syncCodexUsage() { const usage = await fetchApi('/api/codex-usage'); State.codexUsage = usage; renderCodexUsage(); }
function runLocalTelemetry() { if (State.connected) return; let changed = false; State.agents.forEach((agent) => { if (agent.status !== 'working') return; const rates = {low: 2, medium: 4, high: 7, xhigh: 11}; agent.tokens_used = Math.min(agent.token_budget, agent.tokens_used + rates[agent.reasoning_effort]); if (agent.tokens_used >= agent.token_budget) agent.status = 'sleeping'; changed = true; }); if (changed) { State.lastTelemetryAt = new Date(); renderMetricsPanel(); } }
function makeSlimesWander() { State.agents.filter((agent) => agent.status !== 'working' && LoungeRoutes[agent.id]).forEach((agent) => { const route = LoungeRoutes[agent.id]; agent.loungeStep = ((agent.loungeStep ?? -1) + 1) % route.length; agent.sleep = [...route[agent.loungeStep]]; agent.moving = true; }); renderSlimeRoom(); setTimeout(() => { State.agents.forEach((agent) => { agent.moving = false; }); renderSlimeRoom(); }, 2100); }
function localRouteMission(prompt) { const value = prompt.toLowerCase(); const selected = ['director','nexus']; if (/investiga|fuente|busca|compet|analiza/.test(value)) selected.push('scout'); if (/crea|constru|código|codigo|web|diseña|disena/.test(value)) selected.push('forge'); if (/revisa|calidad|error|test|riesgo/.test(value)) selected.push('sentinel'); if (/diseño|diseno|visual|estética|estetica|ui|ux|pixel|animación|animacion|ilustración|ilustracion|arte|estilo|interfaz|layout/.test(value)) selected.push('muse'); return [...new Set(selected.length === 2 ? [...selected, 'scout'] : selected)]; }
async function submitMission(event) { event.preventDefault(); const input = $('#missionInput'); const prompt = input.value.trim(); if (!prompt) return; let assigned = localRouteMission(prompt); State.agents.forEach((agent) => { if (!assigned.includes(agent.id)) { agent.status = 'sleeping'; agent.visualPhase = undefined; } }); triggerWorkAnimation(assigned); $('#missionSummary').textContent = 'Trabajo iniciado. Los slimes van hacia su despacho…'; input.value = ''; renderDashboard(); try { const result = await fetchApi('/api/dispatch', {method:'POST', body:JSON.stringify({prompt})}); assigned = result.agent_ids; triggerWorkAnimation(assigned); $('#missionSummary').textContent = result.plan; } catch { $('#missionSummary').textContent = 'Misión iniciada en modo demo.'; } }
async function saveAgentControls() { const agent = getSelectedAgent(); agent.token_budget = Number($('#budgetInput').value); try { const updated = await fetchApi(`/api/agents/${agent.id}/controls`, {method:'POST', body:JSON.stringify({token_budget:agent.token_budget,reasoning_effort:agent.reasoning_effort})}); Object.assign(agent, updated); } catch {} renderDashboard(); }
function bindInteractions() { $('#agentSelect').addEventListener('change', (event) => { State.selectedAgentId = event.target.value; renderControlPanel(); }); $('#effortSelector').addEventListener('click', (event) => { const level = event.target.dataset.effort; if (!level) return; getSelectedAgent().reasoning_effort = level; renderControlPanel(); }); $('#saveControls').addEventListener('click', saveAgentControls); $('#missionForm').addEventListener('submit', submitMission); $('#refreshCodexUsage').addEventListener('click', () => syncCodexUsage().catch(() => {})); document.querySelector('.LiveOpsLayout').addEventListener('click', (event) => { const camera = event.target.closest('[data-camera]'); if (camera) { controlRoomCamera(camera.dataset.camera); return; } const button = event.target.closest('[data-agent-info]'); if (!button) return; const id = button.dataset.agentInfo; State.openAgentId = State.openAgentId === id ? null : id; renderAgentWatchPanels(); }); }
bindInteractions(); renderDashboard(); updateDigitalClock(); syncDashboard().catch(() => { updateConnectionLabel(); }); connectLiveStream(); syncCodexUsage().catch(() => {}); checkForDeployment().catch(() => {}); setInterval(() => syncDashboard().catch(() => {}), 2000); setInterval(() => syncCodexUsage().catch(() => {}), 60000); setInterval(() => checkForDeployment().catch(() => {}), 25000); setInterval(runLocalTelemetry, 1000); setInterval(makeSlimesWander, 4200); setInterval(updateDigitalClock, 1000);
